local sources=game:GetService("HttpService"):JSONDecode([====[{"SpellService.lua":"-- ServerScriptService.VoiceArena.SpellService (ModuleScript)\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal Debris = game:GetService(\"Debris\")\nlocal TweenService = game:GetService(\"TweenService\")\nlocal Config = require(script.Parent.SpellConfig)\nlocal Service = {}\nlocal freezes, burns, cooldowns, globalCooldowns = {}, {}, {}, {}\nlocal effects = workspace:FindFirstChild(\"VoiceArenaEffects\") or Instance.new(\"Folder\")\neffects.Name = \"VoiceArenaEffects\"\neffects.Parent = workspace\n\nlocal function alive(character)\n  if not character then return end\n  local h = character:FindFirstChildOfClass(\"Humanoid\")\n  local root = character:FindFirstChild(\"HumanoidRootPart\")\n  if h and root and h.Health > 0 then return h, root end\nend\nlocal function part(name, size, color, cf, solid)\n  local p = Instance.new(\"Part\")\n  p.Name = name; p.Size = size; p.Color = color; p.CFrame = cf\n  p.Anchored = true; p.CanCollide = solid or false; p.CanTouch = false\n  p.CanQuery = solid or false; p.Material = Enum.Material.Neon\n  p.Parent = effects\n  return p\nend\nlocal function burst(position, color)\n  local p = part(\"SpellImpact\", Vector3.one, color, CFrame.new(position))\n  p.Shape = Enum.PartType.Ball\n  TweenService:Create(p, TweenInfo.new(0.35), { Size = Vector3.new(7,7,7), Transparency = 1 }):Play()\n  Debris:AddItem(p, 0.4)\nend\nlocal function targetFrom(hit)\n  local model = hit:FindFirstAncestorOfClass(\"Model\")\n  while model and not model:FindFirstChildOfClass(\"Humanoid\") do model = model.Parent and model.Parent:FindFirstAncestorOfClass(\"Model\") end\n  return model\nend\nlocal function enemy(caster, character)\n  return character and character ~= caster.Character and alive(character) ~= nil\nend\nlocal function flame(character)\n  local h, root = alive(character)\n  if not h then return end\n  h:TakeDamage(Config.Flame.Damage)\n  -- Recasting refreshes one burn; it never multiplies ticking tasks.\n  if burns[h] then burns[h].untilTime = os.clock() + Config.Flame.BurnSeconds; return end\n  local fire = Instance.new(\"Fire\")\n  fire.Name = \"VoiceBurn\"; fire.Size = 6; fire.Heat = 5; fire.Parent = root\n  local state = { untilTime = os.clock() + Config.Flame.BurnSeconds }\n  burns[h] = state\n  task.spawn(function()\n    local nextTick = os.clock() + 1\n    while h.Parent and h.Health > 0 and root.Parent do\n      task.wait(math.max(0, nextTick - os.clock()))\n      if not h.Parent or h.Health <= 0 or not root.Parent then break end\n      -- Tick at t=1,2,3,4,5 (including the fifth second).\n      if nextTick > state.untilTime + 0.02 then break end\n      h:TakeDamage(Config.Flame.BurnDamage)\n      nextTick += 1\n      if nextTick > state.untilTime + 0.02 then break end\n    end\n    fire:Destroy(); burns[h] = nil\n  end)\nend\nlocal function freeze(character)\n  local h, root = alive(character)\n  if not h then return end\n  if freezes[h] then freezes[h].untilTime = os.clock() + Config.Freeze.Duration; return end\n  local ice = part(\"FrozenPrison\", Vector3.new(5,7,5), Color3.fromRGB(130,220,255), root.CFrame)\n  ice.Material = Enum.Material.Ice; ice.Transparency = 0.35\n  local state = { untilTime = os.clock() + Config.Freeze.Duration, anchored = root.Anchored,\n    walk = h.WalkSpeed, jumpPower = h.JumpPower, jumpHeight = h.JumpHeight, rotate = h.AutoRotate }\n  freezes[h] = state\n  character:SetAttribute(\"VoiceFrozen\", true)\n  root.AssemblyLinearVelocity = Vector3.zero; root.AssemblyAngularVelocity = Vector3.zero\n  root.Anchored = true; h.WalkSpeed = 0; h.JumpPower = 0; h.JumpHeight = 0; h.AutoRotate = false\n  task.spawn(function()\n    while h.Parent and root.Parent and h.Health > 0 and os.clock() < state.untilTime do task.wait(0.05) end\n    if root.Parent then root.Anchored = state.anchored end\n    if h.Parent then h.WalkSpeed = state.walk; h.JumpPower = state.jumpPower; h.JumpHeight = state.jumpHeight; h.AutoRotate = state.rotate end\n    if character.Parent then character:SetAttribute(\"VoiceFrozen\", false) end\n    ice:Destroy(); freezes[h] = nil\n  end)\nend\nlocal function projectile(player, direction, spell)\n  local _, root = alive(player.Character)\n  if not root then return end\n  local cfg = Config[spell]\n  local color = spell == \"Flame\" and Color3.fromRGB(255,115,35) or Color3.fromRGB(135,225,255)\n  local position = root.Position + Vector3.new(0,1,0) + direction * 2\n  local orb = part(spell .. \"Bolt\", Vector3.new(2,2,2), color, CFrame.new(position))\n  orb.Shape = Enum.PartType.Ball\n  local light = Instance.new(\"PointLight\"); light.Color = color; light.Range = 12; light.Brightness = 3; light.Parent = orb\n  if spell == \"Flame\" then local f = Instance.new(\"Fire\"); f.Size = 3; f.Heat = 0; f.Parent = orb end\n  local params = RaycastParams.new()\n  params.FilterType = Enum.RaycastFilterType.Exclude; params.FilterDescendantsInstances = {player.Character, effects}\n  -- Include solid waves as blockers while excluding cosmetic effects.\n  params.FilterDescendantsInstances = {player.Character, orb}\n  params.RespectCanCollide = false\n  local traveled = 0\n  task.spawn(function()\n    while orb.Parent and traveled < cfg.Range do\n      local dt = RunService.Heartbeat:Wait()\n      local distance = math.min(cfg.Speed * dt, cfg.Range - traveled)\n      local step = direction * distance\n      local hit = workspace:Spherecast(position, 0.8, step, params)\n      if hit then\n        local character = targetFrom(hit.Instance)\n        if enemy(player, character) then if spell == \"Flame\" then flame(character) else freeze(character) end end\n        burst(hit.Position, color); break\n      end\n      position += step; traveled += distance; orb.Position = position\n    end\n    orb:Destroy()\n  end)\nend\nlocal function wave(player, direction)\n  local _, root = alive(player.Character)\n  if not root then return end\n  -- A water wall remains upright and moves across the arena floor.\n  local horizontal = Vector3.new(direction.X,0,direction.Z)\n  if horizontal.Magnitude < 0.1 then horizontal = Vector3.new(root.CFrame.LookVector.X,0,root.CFrame.LookVector.Z) end\n  horizontal = horizontal.Unit\n  local cfg = Config.Wave\n  local position = root.Position + horizontal * 7 + Vector3.new(0,3,0)\n  local size = Vector3.new(cfg.Width, cfg.Height, cfg.Depth)\n  local wall = part(\"WaveWall\", size, Color3.fromRGB(35,175,230), CFrame.lookAt(position, position + horizontal), true)\n  wall.Material = Enum.Material.Glass; wall.Transparency = 0.3\n  local crest = part(\"WaveFoam\", Vector3.new(cfg.Width,1.4,cfg.Depth+1), Color3.fromRGB(210,255,255), wall.CFrame * CFrame.new(0,cfg.Height/2,0))\n  local overlap = OverlapParams.new(); overlap.FilterType = Enum.RaycastFilterType.Exclude\n  overlap.FilterDescendantsInstances = {effects, player.Character}\n  local started = os.clock()\n  local pushed = {}\n  local function pushInside()\n    local seen = {}\n    for _, hit in ipairs(workspace:GetPartBoundsInBox(wall.CFrame, size + Vector3.new(2,0,4), overlap)) do\n      local character = targetFrom(hit)\n      if character and not seen[character] and enemy(player, character) then\n        seen[character] = true\n        local h, targetRoot = alive(character)\n        if h and not targetRoot.Anchored then\n          if not pushed[targetRoot] then\n            pushed[targetRoot] = true\n            pcall(function() targetRoot:SetNetworkOwner(nil) end)\n          end\n          -- Move caught targets ahead of the obstacle, with an arena raycast to avoid shoving through walls.\n          local localPosition = wall.CFrame:PointToObjectSpace(targetRoot.Position)\n          local ahead = wall.CFrame:PointToWorldSpace(Vector3.new(localPosition.X,localPosition.Y,-cfg.Depth/2-3))\n          local displacement = ahead - targetRoot.Position\n          local ray = RaycastParams.new(); ray.FilterType = Enum.RaycastFilterType.Exclude\n          ray.FilterDescendantsInstances = {effects, character, player.Character}\n          local blocker = workspace:Raycast(targetRoot.Position, displacement, ray)\n          if not blocker then targetRoot.CFrame += displacement end\n          targetRoot.AssemblyLinearVelocity = horizontal * cfg.PushSpeed + Vector3.new(0,math.max(2,targetRoot.AssemblyLinearVelocity.Y),0)\n        end\n      end\n    end\n  end\n  task.spawn(function()\n    local elapsed = 0\n    while wall.Parent and elapsed < cfg.Duration do\n      local dt = RunService.Heartbeat:Wait()\n      dt = math.min(dt, cfg.Duration - elapsed)\n      -- Substep to keep the swept obstacle from skipping targets on slow frames.\n      local steps = math.max(1, math.ceil(dt * cfg.Speed / 1.5))\n      for _ = 1, steps do\n        position += horizontal * cfg.Speed * dt / steps\n        wall.CFrame = CFrame.lookAt(position, position + horizontal)\n        crest.CFrame = wall.CFrame * CFrame.new(0,cfg.Height/2,0)\n        pushInside()\n      end\n      elapsed = os.clock() - started\n    end\n    wall:Destroy(); crest:Destroy()\n    for targetRoot in pairs(pushed) do if targetRoot.Parent and not targetRoot.Anchored then pcall(function() targetRoot:SetNetworkOwnershipAuto() end) end end\n  end)\nend\nfunction Service.Cast(player, spell, direction)\n  local cfg = Config[spell]\n  if type(cfg) ~= \"table\" or not (spell == \"Flame\" or spell == \"Freeze\" or spell == \"Wave\") then return false, \"Unknown spell\" end\n  local h = alive(player.Character)\n  if not h then return false, \"Respawn first\" end\n  if player.Character:GetAttribute(\"VoiceFrozen\") then return false, \"You are frozen\" end\n  if typeof(direction) ~= \"Vector3\" or direction.Magnitude < 0.5 or direction.Magnitude > 1.5 then return false, \"Aim unavailable\" end\n  for _, v in ipairs({direction.X,direction.Y,direction.Z}) do if v ~= v or math.abs(v) > 1.5 then return false, \"Invalid aim\" end end\n  local now = os.clock()\n  cooldowns[player] = cooldowns[player] or {}\n  local readyAt = cooldowns[player][spell] or 0\n  if now < readyAt then return false, string.format(\"%s ready in %.1fs\",spell,readyAt-now) end\n  if now < (globalCooldowns[player] or 0) then return false, \"Speak one spell at a time\" end\n  cooldowns[player][spell] = now + cfg.Cooldown; globalCooldowns[player] = now + Config.GlobalCooldown\n  direction = direction.Unit\n  if spell == \"Wave\" then wave(player, direction) else projectile(player, direction, spell) end\n  return true, cfg.Cooldown\nend\nPlayers.PlayerRemoving:Connect(function(player) cooldowns[player] = nil; globalCooldowns[player] = nil end)\nreturn Service\n","SpellConfig.lua":"-- ServerScriptService.VoiceArena.SpellConfig (ModuleScript)\nreturn {\n  BridgeUrl = \"http://127.0.0.1:8787\", -- Console helper on this PC; Studio playtests only.\n  BridgeToken = \"472d5c40354bb828f40425e12db348bee87ef7031087e2bcacea7306c2b0faa0\", -- Must match BRIDGE_TOKEN in bridge/.env. SERVER ONLY.\n  PollInterval = 0.15, -- Pause after each spell batch; idle polls wait up to 8 seconds.\n  EnableStudioKeyboard = true, -- F/G/H are accepted only in Studio.\n  GlobalCooldown = 0.35,\n  Flame = { Cooldown = 2, Damage = 20, BurnDamage = 4, BurnSeconds = 5, Speed = 100, Range = 110 },\n  Freeze = { Cooldown = 7, Duration = 5, Speed = 90, Range = 100 },\n  Wave = { Cooldown = 8, Duration = 5, Speed = 18, Width = 24, Height = 12, Depth = 5, PushSpeed = 30 },\n}\n","VoiceArenaClient.client.lua":"-- StarterPlayer.StarterPlayerScripts.VoiceArenaClient (LocalScript)\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal RunService = game:GetService(\"RunService\")\nlocal UserInputService = game:GetService(\"UserInputService\")\nlocal player = Players.LocalPlayer\nlocal mouse = player:GetMouse()\nlocal remotes = ReplicatedStorage:WaitForChild(\"VoiceArena\")\nlocal feedback, aim, test = remotes:WaitForChild(\"Feedback\"), remotes:WaitForChild(\"Aim\"), remotes:WaitForChild(\"StudioCast\")\nlocal gui = Instance.new(\"ScreenGui\"); gui.Name = \"VoiceArenaHUD\"; gui.ResetOnSpawn = false; gui.Parent = player:WaitForChild(\"PlayerGui\")\nlocal panel = Instance.new(\"Frame\"); panel.Size = UDim2.new(0,450,0,180); panel.Position = UDim2.new(0.5,-225,1,-194)\npanel.BackgroundColor3 = Color3.fromRGB(10,18,35); panel.BackgroundTransparency = 0.08; panel.Parent = gui\nInstance.new(\"UICorner\",panel).CornerRadius = UDim.new(0,14)\nlocal stroke = Instance.new(\"UIStroke\",panel); stroke.Color = Color3.fromRGB(65,100,135); stroke.Transparency = 0.4\nlocal scale = Instance.new(\"UIScale\",panel)\nlocal function label(text, y, height, size, color)\n  local l = Instance.new(\"TextLabel\"); l.Size = UDim2.new(1,-24,0,height); l.Position = UDim2.fromOffset(12,y)\n  l.BackgroundTransparency = 1; l.Text = text; l.TextSize = size; l.Font = Enum.Font.GothamMedium\n  l.TextColor3 = color or Color3.fromRGB(220,235,255); l.TextWrapped = true; l.Parent = panel; return l\nend\nlabel(\"VOICE ARENA  /  KNIGHT HACKS IX\",8,24,14,Color3.fromRGB(145,226,236))\nlocal status = label(\"Waiting for the local voice console\",35,24,13)\nlocal source = label(\"Run Start.cmd and enter your ElevenLabs key\",61,24,13)\nlocal spells = label(\"FLAME   ·   FREEZE   ·   WAVE\",90,29,17)\nlocal message = label(\"Aim with your mouse. Say one spell, then pause.\",127,38,12)\nlocal cooldowns, studio = {}, false\nfeedback.OnClientEvent:Connect(function(event)\n  if event.kind == \"bridge\" then\n    studio = event.studio\n    status.Text = event.connected and \"Local voice console connected\" or \"Voice console offline — run Start.cmd\"\n    source.Text = event.voiceActive and \"Console microphone controls your player\" or \"Select your player in the console\"\n    if studio then message.Text = \"Studio testing: F Flame · G Freeze · H Wave. Aim with mouse.\" end\n  elseif event.kind == \"cast\" then\n    if event.ok then cooldowns[event.spell] = os.clock() + event.value; message.Text = event.spell .. \" cast!\"\n    else message.Text = tostring(event.value) end\n  end\nend)\nUserInputService.InputBegan:Connect(function(input, handled)\n  if handled or not studio or UserInputService:GetFocusedTextBox() then return end\n  local spell = ({ [Enum.KeyCode.F] = \"Flame\", [Enum.KeyCode.G] = \"Freeze\", [Enum.KeyCode.H] = \"Wave\" })[input.KeyCode]\n  if spell then test:FireServer(spell) end\nend)\nlocal accumulated = 0\nRunService.RenderStepped:Connect(function(dt)\n  local camera = workspace.CurrentCamera\n  if camera then scale.Scale = math.min(1, (camera.ViewportSize.X-20)/450) end\n  accumulated += dt\n  if accumulated < 0.1 then return end\n  accumulated = 0\n  local character = player.Character\n  local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n  if root then\n    local direction = mouse.Hit.Position - (root.Position + Vector3.new(0,1,0))\n    if direction.Magnitude > 0.1 then aim:FireServer(direction.Unit) end\n  end\n  local texts = {}\n  for _, spell in ipairs({\"Flame\",\"Freeze\",\"Wave\"}) do\n    local remaining = math.max(0,(cooldowns[spell] or 0)-os.clock())\n    table.insert(texts, remaining > 0 and string.format(\"%s %.1fs\",spell,remaining) or (spell .. \" READY\"))\n  end\n  spells.Text = table.concat(texts,\"  ·  \")\nend)\n","VoiceArenaServer.server.lua":"-- ServerScriptService.VoiceArena.VoiceArenaServer (Script)\nlocal Players = game:GetService(\"Players\")\nlocal HttpService = game:GetService(\"HttpService\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal RunService = game:GetService(\"RunService\")\nlocal Config = require(script.Parent.SpellConfig)\nif not RunService:IsStudio() then\n  warn(\"VoiceArena console bridge runs only in local Studio playtests.\")\n  return\nend\nlocal Spells = require(script.Parent.SpellService)\nlocal folder = ReplicatedStorage:FindFirstChild(\"VoiceArena\") or Instance.new(\"Folder\")\nfolder.Name = \"VoiceArena\"; folder.Parent = ReplicatedStorage\nlocal function remote(name)\n  local r = folder:FindFirstChild(name) or Instance.new(\"RemoteEvent\")\n  r.Name = name; r.Parent = folder; return r\nend\nlocal aimRemote, feedback, testRemote = remote(\"Aim\"), remote(\"Feedback\"), remote(\"StudioCast\")\nlocal aims, lastAim, lives, voiceActive = {}, {}, {}, {}\nlocal session = game.JobId ~= \"\" and game.JobId or HttpService:GenerateGUID(false)\nlocal bridgeUrl = Config.BridgeUrl or \"http://127.0.0.1:8787\"\nassert(string.match(bridgeUrl,\"^http://127%.0%.0%.1:%d+$\"), \"VoiceArena requires a loopback console URL\")\nlocal connected = false\nlocal function state(player)\n  feedback:FireClient(player, { kind = \"bridge\", connected = connected, voiceActive = voiceActive[player] or false,\n    configured = bridgeUrl ~= \"\", studio = RunService:IsStudio() and Config.EnableStudioKeyboard })\nend\nlocal function characterAdded(player)\n  lives[player] = HttpService:GenerateGUID(false); aims[player] = nil; voiceActive[player] = nil\n  task.delay(1, function() if player.Parent then state(player) end end)\nend\nlocal function playerAdded(player)\n  player.CharacterAdded:Connect(function() characterAdded(player) end)\n  if player.Character then characterAdded(player) end\nend\nPlayers.PlayerAdded:Connect(playerAdded)\nfor _, player in ipairs(Players:GetPlayers()) do playerAdded(player) end\nPlayers.PlayerRemoving:Connect(function(player)\n  aims[player] = nil; lastAim[player] = nil; lives[player] = nil; voiceActive[player] = nil\nend)\naimRemote.OnServerEvent:Connect(function(player, direction)\n  local now = os.clock()\n  if now - (lastAim[player] or 0) < 0.08 then return end\n  lastAim[player] = now\n  if typeof(direction) ~= \"Vector3\" then return end\n  for _, v in ipairs({direction.X,direction.Y,direction.Z}) do if v ~= v or math.abs(v) > 2 then return end end\n  if direction.Magnitude < 0.5 or direction.Magnitude > 1.5 then return end\n  aims[player] = { direction = direction.Unit, at = now }\nend)\nlocal function cast(player, spell)\n  local root = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n  if not root then return end\n  local aim = aims[player]\n  local direction = aim and os.clock() - aim.at < 1 and aim.direction or root.CFrame.LookVector\n  local ok, value = Spells.Cast(player, spell, direction)\n  feedback:FireClient(player, { kind = \"cast\", spell = spell, ok = ok, value = value })\nend\nlocal lastTest = {}\ntestRemote.OnServerEvent:Connect(function(player, spell)\n  if not RunService:IsStudio() or not Config.EnableStudioKeyboard or type(spell) ~= \"string\" then return end\n  local now = os.clock()\n  if now - (lastTest[player] or 0) < 0.1 then return end\n  lastTest[player] = now; cast(player, spell)\nend)\nPlayers.PlayerRemoving:Connect(function(p) lastTest[p] = nil end)\n\ntask.spawn(function()\n  local ack, processed = {}, {}\n  local failures = 0\n  while true do\n    if bridgeUrl == \"\" or Config.BridgeToken == \"\" then\n      connected = false; task.wait(2); continue\n    end\n    local roster = {}\n    for _, player in ipairs(Players:GetPlayers()) do\n      table.insert(roster, { userId = player.UserId, name = player.Name, life = lives[player] or \"loading\" })\n    end\n    local ok, data = pcall(function()\n      local response = HttpService:RequestAsync({\n        Url = bridgeUrl .. \"/v1/poll\", Method = \"POST\",\n        Headers = { [\"content-type\"] = \"application/json\", [\"authorization\"] = \"Bearer \" .. Config.BridgeToken },\n        Body = HttpService:JSONEncode({ session = session, players = roster, ack = ack, waitSeconds = 8 }),\n        Timeout = 12,\n      })\n      if not response.Success then error(\"Bridge HTTP \" .. response.StatusCode) end\n      local decoded = HttpService:JSONDecode(response.Body)\n      assert(type(decoded) == \"table\" and type(decoded.players) == \"table\" and type(decoded.commands) == \"table\", \"Invalid bridge response\")\n      return decoded\n    end)\n    if ok then\n      local wasConnected = connected; connected = true; failures = 0; ack = {}\n      for _, info in ipairs(data.players) do\n        if type(info) == \"table\" and type(info.userId) == \"number\" and type(info.voiceActive) == \"boolean\" then\n          local player = Players:GetPlayerByUserId(info.userId)\n          if player and (voiceActive[player] ~= info.voiceActive or not wasConnected) then voiceActive[player] = info.voiceActive; state(player) end\n        end\n      end\n      for index, command in ipairs(data.commands) do\n        if index > 128 then break end\n        if type(command) == \"table\" and type(command.id) == \"string\" and #command.id <= 100 then\n          table.insert(ack, command.id)\n          if not processed[command.id] then\n            processed[command.id] = os.clock()\n            local player = type(command.userId) == \"number\" and Players:GetPlayerByUserId(command.userId)\n            -- Both processes run on this PC. Measure command age, not the idle long-poll duration.\n            local age = type(command.createdAt) == \"number\" and DateTime.now().UnixTimestampMillis - command.createdAt or math.huge\n            if player and lives[player] == command.life and type(command.spell) == \"string\" and\n              age >= -1000 and age < 2500 then\n                print(\"[VoiceArena command] \" .. command.spell)\n                cast(player, command.spell)\n              end\n          end\n        end\n      end\n      for id, time in pairs(processed) do if os.clock() - time > 60 then processed[id] = nil end end\n    else\n      failures += 1\n      if connected or failures == 1 then\n        warn(\"[VoiceArena] Bridge unavailable; verify URL, token, HTTP permission, and running service.\")\n        connected = false\n        for _, player in ipairs(Players:GetPlayers()) do state(player) end\n      end\n    end\n    task.wait(ok and Config.PollInterval or math.min(8, 2 ^ math.min(failures,3)))\n  end\nend)\n"}]====])
