local function upsert(parent,name,class,source)
 local obj=parent:FindFirstChild(name) or Instance.new(class)
 assert(obj.ClassName==class,"Script name conflict: "..name)
 obj.Name=name;obj.Source=source;obj.Parent=parent
end
